// Names that are also towns or a common word elsewhere: they mean a barrio only when the city says which one.
const NEEDS_CITY = new Set(["centro", "la paloma", "colon", "flores", "bella vista", "constitucion", "san nicolas"]);

export interface BarrioTarget {
  city: BarrioCity;
  label: string; // how the person's barrio is named back (display name or the alias they used)
  names: string[]; // official polygon names
}

function lookupIn(key: BarrioCityKey, zona: string): BarrioTarget | null {
  const alias = BARRIO_ALIASES[key][zona];
  if (alias) return { city: BARRIO_CITIES[key], label: alias.label, names: alias.names };
  for (const [official, display] of Object.entries(BARRIO_DISPLAY[key])) {
    if (normalizeText(official) === zona || normalizeText(display) === zona) {
      return { city: BARRIO_CITIES[key], label: display, names: [official] };
    }
  }
  return null;
}

/**
 * The official barrio the router's zona names, or null to keep today's address search. Only Montevideo and CABA have
 * polygons. With no city, a barrio name is used when it is unique among both cities and not a town name elsewhere.
 */
export function resolveBarrio(input: { ciudad: string | null; zona: string | null; pais: string | null }): BarrioTarget | null {
  if (!input.zona) return null;
  const zona = normalizeText(input.zona).replace(/^(el |los )?barrio (de )?/, "");
  if (!zona) return null;
  const ciudad = input.ciudad ? normalizeText(input.ciudad) : "";
  if (ciudad) {
    const key = CITY_NAMES[ciudad];
    return key ? lookupIn(key, zona) : null;
  }
  if (NEEDS_CITY.has(zona)) return null;
  const keys = (Object.keys(BARRIO_CITIES) as BarrioCityKey[])
    .filter((k) => !input.pais || BARRIO_CITIES[k].country === input.pais);
  const found = keys.map((k) => lookupIn(k, zona)).filter((t): t is BarrioTarget => t !== null);
  return found.length === 1 ? found[0] : null;
}

function ringContains(ring: number[], x: number, y: number): boolean {
  let inside = false;
  for (let i = 0, j = ring.length - 2; i < ring.length; j = i, i += 2) {
    const xi = ring[i], yi = ring[i + 1], xj = ring[j], yj = ring[j + 1];
    if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

function shapeContains(shape: BarrioShape, x: number, y: number): boolean {
  const [minX, minY, maxX, maxY] = shape.bbox;
  if (x < minX || x > maxX || y < minY || y > maxY) return false;
  let hits = 0;
  for (const ring of shape.rings) if (ringContains(ring, x, y)) hits++;
  return hits % 2 === 1;
}

/** Kilometres from a point to the nearest edge of a shape (0 when inside). Local equirectangular: < 1% off here. */
function kmToShape(shape: BarrioShape, x: number, y: number): number {
  if (shapeContains(shape, x, y)) return 0;
  const kx = 111.32 * Math.cos((y * Math.PI) / 180), ky = 110.57;
  let best = Infinity;
  for (const ring of shape.rings) {
    for (let i = 0, j = ring.length - 2; i < ring.length; j = i, i += 2) {
      const ax = (ring[j] - x) * kx, ay = (ring[j + 1] - y) * ky;
      const dx = (ring[i] - ring[j]) * kx, dy = (ring[i + 1] - ring[j + 1]) * ky;
      const len2 = dx * dx + dy * dy;
      const t = len2 ? Math.max(0, Math.min(1, -(ax * dx + ay * dy) / len2)) : 0;
      best = Math.min(best, Math.hypot(ax + t * dx, ay + t * dy));
    }
  }
  return best;
}

const SHAPES_BY_NAME: Record<BarrioCityKey, Map<string, BarrioShape>> = {
  montevideo: new Map(BARRIO_SHAPES.montevideo.map((s) => [s.name, s])),
  caba: new Map(BARRIO_SHAPES.caba.map((s) => [s.name, s])),
};

/** The official barrio a point falls in, or null (outside the city, or no coordinates). */
export function officialBarrioAt(key: BarrioCityKey, lat: unknown, lng: unknown): string | null {
  const y = Number(lat), x = Number(lng);
  if (lat == null || lng == null || !Number.isFinite(x) || !Number.isFinite(y)) return null;
  for (const shape of BARRIO_SHAPES[key]) if (shapeContains(shape, x, y)) return shape.name;
  return null;
}

/** The display name of the barrio a point falls in, or null. */
export function barrioAt(key: BarrioCityKey, lat: unknown, lng: unknown): string | null {
  const official = officialBarrioAt(key, lat, lng);
  return official ? BARRIO_DISPLAY[key][official] ?? null : null;
}

/** Kilometres from a point to the target barrio (0 inside it; Infinity with no coordinates). */
export function kmToBarrio(target: BarrioTarget, lat: unknown, lng: unknown): number {
  const y = Number(lat), x = Number(lng);
  if (lat == null || lng == null || !Number.isFinite(x) || !Number.isFinite(y)) return Infinity;
  const shapes = SHAPES_BY_NAME[target.city.key];
  return Math.min(...target.names.map((n) => kmToShape(shapes.get(n) as BarrioShape, x, y)));
}

// "Sumar los más cercanos": a place outside the barrio counts as nearby within this distance of its edge.
export const NEARBY_KM = 1.5;

export interface BarrioSplit<T> {
  inside: T[]; // in the barrio, in the order given, each with `barrio`
  nearby: { barrio: string; count: number }[]; // the others within NEARBY_KM, grouped by their own barrio
  nearbyTotal: number;
}

/** Split a city's rows (already filtered by category / level, in database order) by the target barrio. */
export function splitByBarrio<T extends Record<string, unknown>>(rows: T[], target: BarrioTarget): BarrioSplit<T & { barrio: string | null }> {
  const inside: (T & { barrio: string | null })[] = [];
  const near = new Map<string, { count: number; km: number }>();
  let nearbyTotal = 0;
  for (const row of rows) {
    const official = officialBarrioAt(target.city.key, row.lat, row.lng);
    const barrio = official ? BARRIO_DISPLAY[target.city.key][official] ?? null : null;
    if (official && target.names.includes(official)) {
      inside.push({ ...row, barrio });
      continue;
    }
    const km = kmToBarrio(target, row.lat, row.lng);
    if (barrio && km <= NEARBY_KM) {
      nearbyTotal++;
      const prev = near.get(barrio);
      near.set(barrio, { count: (prev?.count ?? 0) + 1, km: Math.min(prev?.km ?? Infinity, km) });
    }
  }
  const nearby = [...near.entries()]
    .sort((a, b) => b[1].count - a[1].count || a[1].km - b[1].km)
    .map(([barrio, v]) => ({ barrio, count: v.count }));
  return { inside, nearby, nearbyTotal };
}
